/**
 * Observation and Synchronization Metadata Utilities
 *
 * Distinguishes between genuine employee-submitted inspection observations
 * (notes, remarks, defects, negative answers) and internal system-generated
 * synchronization / reconciliation metadata.
 */

export const SYSTEM_SYNC_METADATA_MARKERS = [
  'Auto-completed during sync catch-up',
  'Auto-completed upon starting a new patrol session.',
] as const;

/**
 * Checks whether a given remark string was generated by the system for
 * synchronization / reconciliation rather than entered by an employee.
 *
 * Adheres to narrow scoping:
 * - Exact match against known system catch-up messages.
 * - Structured system prefix `[SYSTEM:` or `[SYSTEM]`.
 * - Does NOT filter genuine employee remarks containing words like "sync" or "completed".
 */
export function isSystemSyncRemark(remark?: string | null): boolean {
  if (!remark) return false;
  const trimmed = remark.trim();
  if (!trimmed) return false;

  for (const marker of SYSTEM_SYNC_METADATA_MARKERS) {
    if (trimmed === marker) return true;
  }

  if (trimmed.startsWith('[SYSTEM:') || trimmed.startsWith('[SYSTEM]')) {
    return true;
  }

  return false;
}

/**
 * Strips system prefix if present, returning the human-readable message.
 */
export function cleanSystemRemark(remark?: string | null): string | null {
  if (!remark) return null;
  const trimmed = remark.trim();
  if (!trimmed) return null;
  return trimmed.replace(/^\[SYSTEM(?::[A-Z_]+)?\]\s*/i, '');
}

export interface ExtractedObservation {
  title: string;
  description?: string;
  severity?: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  type?: 'CHECKPOINT_NOTE' | 'SUBTASK_REMARK' | 'FAILED_TASK' | 'INCIDENT' | 'SNAG';
}

/**
 * Extracts and deduplicates customer-facing observations from a completed patrol session.
 * Excludes technical synchronization catch-up messages while preserving:
 * - Legitimate subtask remarks entered by employees
 * - Checkpoint remarks / officer notes
 * - Negative inspection answers (answer === 'NO')
 * - Incidents and Snags reported during the patrol
 */
export function extractPatrolObservations(session: any): ExtractedObservation[] {
  const observations: ExtractedObservation[] = [];
  const seenObservationKeys = new Set<string>();

  const addObservation = (obs: ExtractedObservation) => {
    // Deduplication key based on title + description
    const key = `${obs.title.trim().toLowerCase()}|${(obs.description || '').trim().toLowerCase()}`;
    if (!seenObservationKeys.has(key)) {
      seenObservationKeys.add(key);
      observations.push(obs);
    }
  };

  const checkpoints = session.checkpoints || [];

  for (const cp of checkpoints) {
    const gateName = cp.gate?.name || 'Checkpoint';

    // 1. Checkpoint-level notes/remarks entered by employee
    if (cp.remarks && !isSystemSyncRemark(cp.remarks)) {
      addObservation({
        title: `Checkpoint: ${gateName} — Officer Note`,
        description: cp.remarks.trim(),
        type: 'CHECKPOINT_NOTE',
      });
    }

    // 2. Sub-task responses
    const subTaskResponses = cp.subTaskResponses || [];
    for (const str of subTaskResponses) {
      // Ignore system-generated sync catch-up remarks
      const isSystem = isSystemSyncRemark(str.remarks);
      const taskName =
        str.taskNameSnapshot ||
        str.gateSubTask?.taskName ||
        'Inspection Item';

      // 2a. Failed inspection task (Answer: NO)
      if (str.answer === 'NO') {
        const descParts: string[] = [];
        if (str.remarks && !isSystem) {
          descParts.push(`Remark: ${str.remarks.trim()}`);
        } else {
          descParts.push('Task verification failed (Answer: NO)');
        }
        addObservation({
          title: `Checkpoint: ${gateName} — Failed Check: ${taskName}`,
          description: descParts.join(' — '),
          severity: 'HIGH',
          type: 'FAILED_TASK',
        });
      }
      // 2b. Passed or non-negative task, but with genuine employee remarks
      else if (str.remarks && !isSystem) {
        addObservation({
          title: `Checkpoint: ${gateName} — ${taskName} Note`,
          description: str.remarks.trim(),
          type: 'SUBTASK_REMARK',
        });
      }
    }
  }

  // 3. Incidents reported during session (avoid duplicating auto-created incidents from failed tasks)
  const incidents = session.incidents || [];
  for (const inc of incidents) {
    // If the incident description was auto-generated from subtask answer NO, avoid duplicate observation
    const isAutoFromSubtask =
      inc.description?.includes('Sub-Task Answer: NO') ||
      inc.description?.includes('Automatic Observation');

    if (!isAutoFromSubtask) {
      addObservation({
        title: `Incident: ${inc.title || inc.type || 'Reported Incident'}`,
        description: inc.description || undefined,
        severity: inc.severity || 'MEDIUM',
        type: 'INCIDENT',
      });
    }
  }

  // 4. Snags reported during session
  const snags = session.snags || [];
  for (const snag of snags) {
    addObservation({
      title: `Snag / Defect: ${snag.title || snag.name || 'Defect'}`,
      description: snag.description || undefined,
      severity: snag.priority || 'MEDIUM',
      type: 'SNAG',
    });
  }

  return observations;
}

